<?php

namespace Database\Seeders;

use Illuminate\Database\Seeder;

class DatabaseSeeder extends Seeder
{
    /**
     * Seed the application's database.
     *
     * Midway Weather has no user accounts. The only seedable data is demo
     * weather, which is generated by the dedicated `weather:demo` command so
     * the same logic is reachable from both the CLI and `db:seed`.
     */
    public function run(): void
    {
        $this->command->call('weather:demo');
    }
}
